(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-954":{scenario:{company:"Green Ridge Swine Farm",supervisor:{name:"Đinh Công Tuấn",role:{vi:"Bác sĩ thú y phụ trách trại",en:"Farm Veterinarian"}},ref_code:"TY-1108",title:{vi:"Bảo quản đúng. Tính liều theo cân. Ngừng thuốc đủ ngày.",en:"Store it right. Dose by weight. Respect withdrawal."},brief:{vi:"Đây là tình huống đào tạo. Bạn rà soát nhật ký thú y TY-1108 khu nái. Trại vừa nhận lô vaccine lở mồm long móng vô hoạt dạng nhũ dầu. Nái N-217 viêm tử cung được chỉ định tiêm oxytetracycline tác dụng kéo dài liều 20 mg/kg, dung dịch 200 mg/mL; cân thực tế 236 kg, nhưng phiếu ghi khối lượng ước lượng 180 kg. Sửa điều kiện bảo quản vaccine và thể tích tiêm (mL), rồi lập báo cáo có căn cứ.",en:"This is a training scenario. You are reviewing veterinary log TY-1108 for the sow unit. The farm has just received inactivated oil-emulsion foot-and-mouth disease vaccine. Sow N-217 with metritis is prescribed long-acting oxytetracycline at 20 mg/kg, 200 mg/mL solution; she weighs 236 kg on the scale, but the sheet shows an estimated 180 kg. Correct the vaccine storage condition and the injection volume (mL), then write an evidence-based report."},reference_title:{vi:"Hướng dẫn sử dụng vaccine & đơn điều trị đã duyệt · TY-1108",en:"Approved vaccine leaflet & treatment order · TY-1108"},fields:[{id:"VACC_STORE",label:{vi:"Điều kiện bảo quản vaccine",en:"Vaccine storage condition"},initial:"-20°C",expected:"2-8°C",choices:["-20°C","2-8°C","15-25°C"],reference:"Tờ hướng dẫn sử dụng vaccine",hint:{vi:"Vaccine vô hoạt nhũ dầu phải bảo quản lạnh, tuyệt đối không để đông đá vì nhũ tương bị phá vỡ, mất hiệu lực.",en:"Inactivated oil-emulsion vaccine must be refrigerated and never frozen, as freezing breaks the emulsion and destroys potency."}},{id:"INJ_ML",label:{vi:"Thể tích tiêm cho nái N-217 (mL)",en:"Injection volume for sow N-217 (mL)"},initial:"18",expected:"23.6",reference:"Phiếu cân & đơn điều trị",ref_value:{vi:"Cân thực tế 236 kg; liều 20 mg/kg; nồng độ 200 mg/mL",en:"Weighed 236 kg; dose 20 mg/kg; concentration 200 mg/mL"},hint:{vi:"Liều thuốc tính theo khối lượng cân thực tế; ước lượng bằng mắt dễ gây thiếu liều và kháng thuốc.",en:"Dose by weighed body weight; visual estimates often cause underdosing and resistance."}}],sop32:{vi:"Thể tích tiêm (mL) = khối lượng cân thực tế (kg) x liều (mg/kg) / nồng độ thuốc (mg/mL); liều lớn chia nhiều vị trí tiêm theo hướng dẫn nhãn.",en:"Injection volume (mL) = weighed body weight (kg) x dose (mg/kg) / concentration (mg/mL); split large volumes across sites as the label directs."},context:{label:"NHẬT KÝ THÚ Y NHÁP / TY-1108",metrics:[{label:{vi:"Khối lượng cân",en:"Weighed body weight"},value:"236 kg"},{label:{vi:"Liều chỉ định",en:"Prescribed dose"},value:"20 mg/kg"},{label:{vi:"Nồng độ thuốc",en:"Concentration"},value:"200 mg/mL"},{label:{vi:"Ngừng thuốc mô phỏng",en:"Training withdrawal"},value:"28 d"}]},crisis:{vi:"Chủ trại nhắn: “Chiều nay thương lái đến bắt mấy nái loại, có cả con N-217 vừa tiêm hôm qua. Cứ cho xuất, sổ thì ghi là tiêm sau khi bán.”",en:"The farm owner messages you: “The trader is coming this afternoon for the cull sows, including N-217 that was injected yesterday. Let her go and record the injection as given after the sale.”"},options:{safe:{vi:"Không xuất nái N-217 khi chưa hết 28 ngày ngừng thuốc (mô phỏng), ghi sổ trung thực, báo bác sĩ thú y phụ trách trại và đề nghị hẹn thương lái sau ngày hết ngừng thuốc.",en:"Do not release sow N-217 before the 28-day withdrawal (training data) ends, keep honest records, inform the farm veterinarian and reschedule the trader after the withdrawal date."},shortcut:{vi:"Cho xuất bán N-217 cùng lô nái loại và ghi ngày tiêm lùi sau ngày bán.",en:"Sell N-217 with the cull sows and backdate the injection to after the sale."},wait:{vi:"Không ý kiến, để chủ trại và thương lái tự thỏa thuận.",en:"Say nothing and let the owner and the trader settle it."}},questions:{vi:["Vì sao vaccine phải bảo quản 2-8°C và nái N-217 cần 23.6 mL? Chứng từ nào chứng minh?","Bạn xử lý yêu cầu xuất bán nái đang trong thời gian ngừng thuốc thế nào để bảo vệ người tiêu dùng và uy tín trại?"],en:["Why must the vaccine be kept at 2-8°C and why does sow N-217 need 23.6 mL? Which documents prove it?","How do you handle the request to sell a sow still in withdrawal while protecting consumers and the farm's reputation?"]},hints:{vi:["Đọc tờ hướng dẫn vaccine và tìm dòng cảnh báo về nhiệt độ bảo quản.","Lấy khối lượng cân thực tế nhân liều rồi chia nồng độ theo SOP mục 3.2.","Đọc lại SOP mục 4.2: vật nuôi trong thời gian ngừng thuốc không được xuất bán; mọi áp lực phải báo bác sĩ thú y."],en:["Read the vaccine leaflet and find the storage temperature warning.","Multiply the weighed body weight by the dose and divide by the concentration as in SOP 3.2.","Re-read SOP 4.2: animals in withdrawal are never sold; any pressure goes to the veterinarian."]}},learning:{summary:{vi:"Kỹ thuật viên chăn nuôi và thú y chăm sóc sức khỏe đàn vật nuôi hằng ngày: theo dõi biểu hiện, thực hiện lịch vaccine, điều trị theo chỉ định của bác sĩ thú y, vận hành an toàn sinh học, quản lý dinh dưỡng và ghi chép sổ sách. Nghề giúp giảm hao hụt, nâng năng suất và bảo đảm thực phẩm an toàn, không tồn dư kháng sinh; đòi hỏi kỹ năng thực hành, quan sát tinh và tuân thủ quy định thú y.",en:"A livestock and veterinary technician looks after herd health every day: observing animals, running the vaccination schedule, giving treatments prescribed by the veterinarian, operating biosecurity, managing nutrition and keeping records. The role cuts losses, raises productivity and keeps food safe and free of antibiotic residues; it requires hands-on skills, sharp observation and veterinary compliance."},responsibilities:{vi:["Theo dõi sức khỏe, ăn uống, thân nhiệt và phát hiện sớm vật nuôi bất thường.","Thực hiện lịch tiêm phòng, bảo quản vaccine đúng dây chuyền lạnh.","Cấp thuốc, tiêm điều trị theo đơn của bác sĩ thú y và tính liều theo khối lượng cân.","Vận hành an toàn sinh học: sát trùng, kiểm soát ra vào, cách ly, xử lý xác.","Ghi nhật ký điều trị, thời gian ngừng thuốc và báo cáo dịch bệnh theo quy định."],en:["Monitor health, feed intake and temperature and spot sick animals early.","Run the vaccination schedule and keep vaccines in the cold chain.","Give medicines and injections prescribed by the veterinarian, dosing by weighed body weight.","Operate biosecurity: disinfection, access control, isolation and carcass disposal.","Keep treatment and withdrawal records and report disease as required."]},competencies:[{name:{vi:"Phát hiện bệnh sớm",en:"Early disease detection"},desc:{vi:"Nhận biết thay đổi về ăn uống, hô hấp, phân, tư thế để báo bác sĩ thú y kịp thời.",en:"Notice changes in appetite, breathing, faeces and posture and alert the veterinarian quickly."}},{name:{vi:"Kỹ thuật tiêm & cấp thuốc",en:"Injection & dosing technique"},desc:{vi:"Tiêm đúng đường, đúng vị trí, đúng cỡ kim và tính liều chính xác theo khối lượng.",en:"Inject by the right route, site and needle size and calculate doses accurately by weight."}},{name:{vi:"Quản lý vaccine & dây chuyền lạnh",en:"Vaccine & cold chain management"},desc:{vi:"Bảo quản, vận chuyển và sử dụng vaccine đúng nhiệt độ, ghi số lô và hạn dùng.",en:"Store, transport and use vaccines at the right temperature, recording batch and expiry."}},{name:{vi:"An toàn sinh học",en:"Biosecurity"},desc:{vi:"Kiểm soát người, xe, vật tư ra vào trại và thực hiện quy trình sát trùng nghiêm ngặt.",en:"Control people, vehicles and supplies entering the farm and apply strict disinfection."}},{name:{vi:"Ghi chép & tuân thủ",en:"Records & compliance"},desc:{vi:"Ghi nhật ký trung thực, theo dõi thời gian ngừng thuốc và từ chối xuất bán sai quy định.",en:"Keep honest logs, track withdrawal periods and refuse non-compliant sales."}}],knowledge:{vi:["Luật Thú y số 79/2015/QH13 và các quy định về phòng, chống dịch bệnh động vật.","Luật Chăn nuôi số 32/2018/QH14 và quy định hạn chế sử dụng kháng sinh trong thức ăn chăn nuôi.","Thời gian ngừng thuốc và giới hạn dư lượng thuốc thú y tối đa (MRL) trong thực phẩm.","Tiêu chuẩn của Tổ chức Thú y Thế giới (WOAH) về an toàn sinh học và phúc lợi động vật.","Sử dụng kháng sinh có trách nhiệm: đúng chẩn đoán, đúng liều, đủ liệu trình, theo đơn thú y."],en:["Veterinary Law No. 79/2015/QH13 and rules on animal disease prevention and control.","Animal Husbandry Law No. 32/2018/QH14 and the restrictions on antibiotics in animal feed.","Withdrawal periods and maximum residue limits (MRL) for veterinary drugs in food.","World Organisation for Animal Health (WOAH) standards on biosecurity and animal welfare.","Responsible antibiotic use: correct diagnosis, correct dose, full course and veterinary prescription."]},tools:["Cân điện tử vật nuôi","Tủ lạnh vaccine có nhiệt kế tự ghi","Bơm tiêm tự động & kim theo cỡ","Nhiệt kế thú y","Phần mềm quản lý đàn"],kpis:{vi:["Tỷ lệ hao hụt, chết theo giai đoạn so với mục tiêu.","Tỷ lệ tiêm phòng đúng lịch, nhiệt độ tủ vaccine luôn trong 2-8°C.","Số vi phạm thời gian ngừng thuốc khi xuất bán (mục tiêu bằng 0).","Lượng kháng sinh sử dụng trên mỗi tấn thịt hơi."],en:["Mortality and losses by stage versus target.","On-schedule vaccination rate with the vaccine fridge always at 2-8°C.","Withdrawal violations at sale (target zero).","Antibiotic use per tonne of live weight."]},day:[{time:"06:30",vi:"Tắm sát trùng vào khu chăn nuôi, kiểm tra nhiệt độ tủ vaccine.",en:"Shower in to the production zone and check the vaccine fridge temperature."},{time:"07:30",vi:"Quan sát đàn, đo thân nhiệt các con bỏ ăn và ghi sổ theo dõi.",en:"Observe the herd, take temperatures of animals off feed and log them."},{time:"09:30",vi:"Tiêm phòng theo lịch, ghi số lô vaccine và vị trí tiêm.",en:"Vaccinate on schedule, recording vaccine batch and injection site."},{time:"14:00",vi:"Điều trị theo đơn của bác sĩ thú y, cân vật nuôi và tính liều.",en:"Treat as prescribed by the veterinarian, weigh animals and calculate doses."},{time:"16:30",vi:"Cập nhật nhật ký điều trị và danh sách vật nuôi đang ngừng thuốc.",en:"Update the treatment log and the list of animals in withdrawal."}],mistakes:{vi:["Ước lượng khối lượng bằng mắt, tiêm thiếu liều gây kháng thuốc hoặc thừa liều gây ngộ độc.","Để vaccine vô hoạt bị đông đá hoặc để ngoài nhiệt độ phòng quá lâu.","Xuất bán vật nuôi chưa hết thời gian ngừng thuốc, gây tồn dư trong thịt."],en:["Estimating weight by eye, underdosing and driving resistance or overdosing and causing toxicity.","Letting inactivated vaccine freeze or sit at room temperature too long.","Selling animals before the withdrawal period ends, leaving residues in meat."]},career:[{vi:"Công nhân chăn nuôi",en:"Stockperson"},{vi:"Kỹ thuật viên chăn nuôi & thú y",en:"Livestock & veterinary technician"},{vi:"Trưởng trại chăn nuôi",en:"Farm manager"},{vi:"Quản lý kỹ thuật chăn nuôi vùng",en:"Regional livestock technical manager"}],glossary:[{term:"Withdrawal period",vi:"Thời gian ngừng thuốc: từ lần dùng thuốc cuối đến khi được giết mổ hoặc khai thác sản phẩm.",en:"Time from the last dose until the animal may be slaughtered or its products used."},{term:"Biosecurity",vi:"An toàn sinh học: các biện pháp ngăn mầm bệnh xâm nhập và lây lan trong trại.",en:"Measures that keep pathogens out of the farm and stop them spreading."},{term:"Cold chain",vi:"Dây chuyền lạnh: giữ vaccine ở nhiệt độ quy định từ nhà sản xuất đến lúc tiêm.",en:"Keeping vaccines at the required temperature from the maker to the injection."},{term:"Inactivated vaccine",vi:"Vaccine vô hoạt: chứa mầm bệnh đã bị bất hoạt, thường có chất bổ trợ nhũ dầu.",en:"Vaccine containing killed pathogens, often with an oil-emulsion adjuvant."},{term:"MRL",vi:"Giới hạn dư lượng tối đa của thuốc thú y được phép trong thịt, sữa, trứng.",en:"Maximum residue limit of a veterinary drug allowed in meat, milk or eggs."}],quiz:[{q:{vi:"Lợn nặng 90 kg, liều 10 mg/kg, thuốc nồng độ 100 mg/mL. Cần tiêm bao nhiêu mL?",en:"A 90 kg pig, dose 10 mg/kg, drug at 100 mg/mL. How many mL are needed?"},options:{vi:["90 mL","0.9 mL","9 mL","10 mL"],en:["90 mL","0.9 mL","9 mL","10 mL"]},answer:2,explain:{vi:"Thể tích = 90 x 10 / 100 = 9 mL.",en:"Volume = 90 x 10 / 100 = 9 mL."}},{q:{vi:"Vaccine vô hoạt dạng nhũ dầu nên được bảo quản thế nào?",en:"How should inactivated oil-emulsion vaccine be stored?"},options:{vi:["2-8°C, không để đông đá","Đông đá ở -20°C","Nhiệt độ phòng","Ngâm trực tiếp trong nước đá"],en:["2-8°C, never frozen","Frozen at -20°C","Room temperature","Directly in ice water"]},answer:0,explain:{vi:"Đông đá làm vỡ nhũ tương và mất hiệu lực vaccine; phải giữ trong 2-8°C.",en:"Freezing breaks the emulsion and destroys potency; keep it at 2-8°C."}},{q:{vi:"Chủ trại muốn bán lợn đang trong thời gian ngừng thuốc. Bạn làm gì?",en:"The owner wants to sell pigs still in withdrawal. What do you do?"},options:{vi:["Đồng ý nếu lợn khỏe","Ghi lùi ngày tiêm","Giao cho thương lái quen","Từ chối, ghi sổ trung thực và báo bác sĩ thú y"],en:["Agree if the pigs look healthy","Backdate the injection","Hand them to a familiar trader","Refuse, keep honest records and inform the veterinarian"]},answer:3,explain:{vi:"Bán vật nuôi chưa hết thời gian ngừng thuốc gây tồn dư kháng sinh trong thịt, vi phạm quy định thú y và an toàn thực phẩm.",en:"Selling animals in withdrawal leaves antibiotic residues in meat and breaks veterinary and food safety rules."}},{q:{vi:"Thời gian ngừng thuốc là gì?",en:"What is a withdrawal period?"},options:{vi:["Thời gian thuốc phát huy tác dụng","Khoảng thời gian từ lần dùng thuốc cuối đến khi được giết mổ, khai thác sản phẩm","Hạn sử dụng của thuốc","Thời gian giữa hai mũi tiêm"],en:["Time for the drug to take effect","Time from the last dose until slaughter or product use is allowed","The drug's expiry date","Interval between two injections"]},answer:1,explain:{vi:"Thời gian ngừng thuốc bảo đảm dư lượng giảm dưới MRL trước khi thịt, sữa, trứng vào chuỗi thực phẩm.",en:"The withdrawal period ensures residues fall below the MRL before meat, milk or eggs enter the food chain."}}],tools_en:["Electronic livestock scale","Vaccine fridge with recording thermometer","Automatic syringes & sized needles","Veterinary thermometer","Herd management software"]}}})})(window.KKR);
